import{_ as t,o,c as s,a0 as r}from"./chunks/framework.DB31oXgM.js";const u=JSON.parse('{"title":"Rollback Netcode Server: Threat Model","description":"","frontmatter":{},"headers":[],"relativePath":"THREAT_MODEL.md","filePath":"THREAT_MODEL.md"}'),n={name:"THREAT_MODEL.md"};function i(a,e,l,d,c,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="rollback-netcode-server-threat-model" tabindex="-1">Rollback Netcode Server: Threat Model <a class="header-anchor" href="#rollback-netcode-server-threat-model" aria-label="Permalink to &quot;Rollback Netcode Server: Threat Model&quot;">​</a></h1><p><strong>Date:</strong> 2026-10-10<br><strong>Version:</strong> 1.0<br><strong>Status:</strong> Final</p><hr><h2 id="executive-summary" tabindex="-1">Executive Summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive Summary&quot;">​</a></h2><p>This document outlines eight primary threats to the rollback netcode system and the mitigations implemented. The system assumes a <strong>trusted LAN environment</strong> and does not provide encryption; QUIC/TLS integration is deferred to Phase 2.</p><hr><h2 id="threat-analysis" tabindex="-1">Threat Analysis <a class="header-anchor" href="#threat-analysis" aria-label="Permalink to &quot;Threat Analysis&quot;">​</a></h2><h3 id="_1-udp-packet-loss-corruption" tabindex="-1">1. <strong>UDP Packet Loss &amp; Corruption</strong> <a class="header-anchor" href="#_1-udp-packet-loss-corruption" aria-label="Permalink to &quot;1. **UDP Packet Loss &amp; Corruption**&quot;">​</a></h3><p><strong>Threat:</strong></p><ul><li>Unencrypted UDP packets can be lost on the network or corrupted during transmission.</li><li>Missing packets cause input lag or rollback failures.</li></ul><p><strong>Severity:</strong> HIGH (affects core gameplay)</p><p><strong>Mitigation:</strong></p><ul><li>5-frame input redundancy: each InputFrame encoded as 5 consecutive frames at source</li><li>Server reconstructs missing frames if &gt;= 1 copy received</li><li>CRC32 checksums on all packet types; corrupted packets discarded</li></ul><p><strong>Design Location:</strong> <code>network::mod.rs</code> (redundancy codec), <code>transport::protocol.rs</code> (CRC validation)</p><p><strong>Verification:</strong> <code>tests/chaos_network_channel.rs</code> — redundancy survives 30% loss; <code>tests/integration_2client_udp.rs</code> — handshake and frame exchange verified</p><hr><h3 id="_2-replay-attacks" tabindex="-1">2. <strong>Replay Attacks</strong> <a class="header-anchor" href="#_2-replay-attacks" aria-label="Permalink to &quot;2. **Replay Attacks**&quot;">​</a></h3><p><strong>Threat:</strong></p><ul><li>Attacker captures old InputFrame packets and replays them later.</li><li>Server accepts replayed inputs → players run wrong moves → desync.</li></ul><p><strong>Severity:</strong> HIGH (game-breaking cheating vector)</p><p><strong>Mitigation:</strong></p><ul><li>Monotonic sequence numbers per player (0, 1, 2, ..., wrapping at u32 max).</li><li>Server only accepts inputs with <code>seq &gt; last_acked_seq</code>.</li><li>Sequence number included in InputFrame header and validated before execution.</li></ul><p><strong>Design Location:</strong> <code>transport::protocol.rs</code> — InputFrame seq field validation</p><p><strong>Verification:</strong> <code>tests/transport_protocol_test.rs::test_input_frame_roundtrip_with_redundancy</code> — seq numbers encoded/decoded correctly</p><hr><h3 id="_3-desync-attacks-e-g-false-positive-cheating" tabindex="-1">3. <strong>Desync Attacks</strong> (e.g., False-Positive Cheating) <a class="header-anchor" href="#_3-desync-attacks-e-g-false-positive-cheating" aria-label="Permalink to &quot;3. **Desync Attacks** (e.g., False-Positive Cheating)&quot;">​</a></h3><p><strong>Threat:</strong></p><ul><li>Player A sends forged game state that differs from Player B&#39;s state.</li><li>Server detects mismatch but Player A claims Player B cheated → unfair rollback.</li></ul><p><strong>Severity:</strong> CRITICAL (breaks integrity)</p><p><strong>Mitigation:</strong></p><ul><li><strong>Deterministic simulation:</strong> All players run identical simulation logic on identical inputs.</li><li><strong>Authoritative checksums:</strong> Server computes state hash after each frame; players echo checksum in StateAck.</li><li><strong>Mismatch detection:</strong> Server compares checksums; if mismatch → authoritative rollback + resync.</li><li><strong>AI guardrails:</strong> ML model (if enabled) flags anomalous state patterns before they propagate.</li></ul><p><strong>Design Location:</strong></p><ul><li><code>game::mod.rs</code> — tick() enforces determinism</li><li><code>desync::detector.rs</code> — checksum computation and mismatch detection</li><li><code>aiml/models/isolation_forest_cheat.py</code> — ML anomaly detection ⏳</li></ul><p><strong>Verification:</strong></p><ul><li><code>tests/simulation_determinism_test.rs::test_forced_desync_detection_and_authoritative_recovery</code> — desync detected and recovered</li><li><code>tests/integration_2client_udp.rs::test_protocol_convergence_100_ticks</code> — 100-tick convergence verified</li></ul><hr><h3 id="_4-session-hijacking" tabindex="-1">4. <strong>Session Hijacking</strong> <a class="header-anchor" href="#_4-session-hijacking" aria-label="Permalink to &quot;4. **Session Hijacking**&quot;">​</a></h3><p><strong>Threat:</strong></p><ul><li>Attacker steals a reconnect token and uses it to reconnect as a legitimate player.</li><li>Server grants the attacker access to the player&#39;s session state.</li></ul><p><strong>Severity:</strong> HIGH (account takeover equivalent)</p><p><strong>Mitigation:</strong></p><ul><li>Reconnect tokens include player ID + session ID + issued timestamp.</li><li>Tokens expire after 30 seconds (configurable via <code>reconnect_timeout_secs</code>).</li><li>Tokens stored in Redis with TTL; lookup fails after expiry.</li><li>Token format includes random nonce (UUID); brute-force infeasible.</li></ul><p><strong>Design Location:</strong> <code>session::mod.rs::ReconnectToken</code>, <code>session::repository.rs::validate_reconnect_token()</code></p><p><strong>Verification:</strong> <code>tests/session_state_machine_test.rs::test_reconnect_token</code> — token expiry validated</p><hr><h3 id="_5-denial-of-service-connection-flood" tabindex="-1">5. <strong>Denial of Service (Connection Flood)</strong> <a class="header-anchor" href="#_5-denial-of-service-connection-flood" aria-label="Permalink to &quot;5. **Denial of Service (Connection Flood)**&quot;">​</a></h3><p><strong>Threat:</strong></p><ul><li>Attacker sends thousands of handshake packets from different IPs to exhaust server resources.</li><li>Server runs out of memory or CPU handling invalid handshakes.</li></ul><p><strong>Severity:</strong> MEDIUM (affects availability, not confidentiality)</p><p><strong>Mitigation:</strong></p><ul><li><strong>Current:</strong> Server processes handshakes sequentially in single thread; invalid handshakes rejected immediately.</li><li><strong>Future:</strong> Rate limiting per IP (⏳ Phase 2); SYN cookies or challenge-response; connection pooling limits.</li></ul><p><strong>Design Location:</strong> <code>network::udp_server.rs</code> — sequential processing</p><p><strong>Note:</strong> Explicit rate limiting not implemented yet. Flagged as ⏳.</p><hr><h3 id="_6-man-in-the-middle-no-encryption" tabindex="-1">6. <strong>Man-in-the-Middle (No Encryption)</strong> <a class="header-anchor" href="#_6-man-in-the-middle-no-encryption" aria-label="Permalink to &quot;6. **Man-in-the-Middle (No Encryption)**&quot;">​</a></h3><p><strong>Threat:</strong></p><ul><li>Attacker on the network intercepts and modifies unencrypted UDP packets.</li><li>Attacker injects forged inputs or state to cause cheating.</li></ul><p><strong>Severity:</strong> CRITICAL (but out of scope for Phase 1)</p><p><strong>Mitigation:</strong></p><ul><li><strong>Out of scope for Phase 1:</strong> Assumes trusted LAN or VPN.</li><li><strong>Deferred to Phase 2:</strong> QUIC/TLS encryption with certificate pinning.</li></ul><p><strong>Design Location:</strong> None (to be added in Phase 2)</p><p><strong>Consequence:</strong> System is <strong>NOT safe for public internet</strong> without encryption.</p><hr><h3 id="_7-orphan-sessions-resource-leak" tabindex="-1">7. <strong>Orphan Sessions (Resource Leak)</strong> <a class="header-anchor" href="#_7-orphan-sessions-resource-leak" aria-label="Permalink to &quot;7. **Orphan Sessions (Resource Leak)**&quot;">​</a></h3><p><strong>Threat:</strong></p><ul><li>Player crashes or loses connection without gracefully disconnecting.</li><li>Server holds session in memory indefinitely → memory leak → eventual server OOM.</li></ul><p><strong>Severity:</strong> MEDIUM (slow attack, high impact if unmitigated)</p><p><strong>Mitigation:</strong></p><ul><li><strong>Heartbeat mechanism:</strong> Players send heartbeat pings every 5–10 seconds during active play.</li><li><strong>Stale detection:</strong> Server scans for sessions with <code>last_heartbeat &lt; now - 40 seconds</code>.</li><li><strong>Cleanup:</strong> Stale sessions marked <code>Cleaned</code> and removed from repository.</li><li><strong>Database TTL:</strong> Postgres <code>session_heartbeat</code> column; Redis reconnect tokens have 60-second TTL.</li></ul><p><strong>Design Location:</strong></p><ul><li><code>session::mod.rs::Session::tick()</code> — heartbeat counter</li><li><code>session::repository.rs::find_stale()</code> — stale detection</li><li><code>backend/migrations/20261010_001_init_schema.sql</code> — heartbeat columns</li></ul><p><strong>Verification:</strong> <code>tests/postgres_redis_integration.rs::test_sessions_crud_and_heartbeat_orphan_detection</code> — stale sessions detected; <code>tests/session_state_machine_test.rs::test_repository_stale_detection</code> — in-memory stale detection</p><hr><h3 id="_8-concurrent-connection-collision-same-port" tabindex="-1">8. <strong>Concurrent Connection Collision (Same Port)</strong> <a class="header-anchor" href="#_8-concurrent-connection-collision-same-port" aria-label="Permalink to &quot;8. **Concurrent Connection Collision (Same Port)**&quot;">​</a></h3><p><strong>Threat:</strong></p><ul><li>Two clients on the same LAN connect to server on same port, causing packet confusion.</li><li>Server cannot distinguish between them → packets routed incorrectly.</li></ul><p><strong>Severity:</strong> LOW (requires same IP + port, unlikely in practice)</p><p><strong>Mitigation:</strong></p><ul><li><strong>Single UDP port design:</strong> Server binds to single port (7777); each client identified by <code>(source_ip, source_port)</code> tuple.</li><li><strong>LAN assumption:</strong> On LAN, each client has unique IP or ephemeral port; collision negligible.</li><li><strong>Multi-region:</strong> Use DNS round-robin or load balancer to distribute across multiple servers on different ports/IPs.</li></ul><p><strong>Design Location:</strong> <code>network::udp_server.rs::UdpServer::bind()</code></p><p><strong>Consequence:</strong> System scales to ~100–1000 concurrent sessions per single-port server on LAN; multi-region deployment ⏳.</p><hr><h2 id="summary-table" tabindex="-1">Summary Table <a class="header-anchor" href="#summary-table" aria-label="Permalink to &quot;Summary Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Threat</th><th>Severity</th><th>Mitigation</th><th>Status</th><th>Implemented in Code</th><th>Verification</th></tr></thead><tbody><tr><td>UDP Loss/Corruption</td><td>HIGH</td><td>5-frame redundancy, CRC</td><td>✅ Implemented</td><td>✅ network::mod.rs, transport::protocol.rs</td><td>chaos_network_channel tests</td></tr><tr><td>Replay Attacks</td><td>HIGH</td><td>Seq numbers, ACK tracking</td><td>✅ Implemented</td><td>✅ transport::protocol.rs::InputFrame</td><td>transport_protocol tests</td></tr><tr><td>Desync Attacks</td><td>CRITICAL</td><td>Determinism, checksums, ML</td><td>✅ Core; ⏳ ML</td><td>✅ Core (game::mod.rs, desync::detector.rs); ⏳ ML</td><td>simulation_determinism tests</td></tr><tr><td>Session Hijacking</td><td>HIGH</td><td>Token expiry, Redis TTL</td><td>✅ Implemented</td><td>✅ session::mod.rs, session::repository.rs</td><td>session_state_machine tests</td></tr><tr><td>DoS (Connection Flood)</td><td>MEDIUM</td><td>Sequential processing</td><td>⏳ Rate limiting</td><td>⏳ D2 (rate limiting trait)</td><td>Monitoring only</td></tr><tr><td>MITM (No Encryption)</td><td>CRITICAL</td><td>Trusted LAN assumption</td><td>⏳ Phase 2</td><td>❌ (QUIC/TLS deferred)</td><td>Out of scope</td></tr><tr><td>Orphan Sessions</td><td>MEDIUM</td><td>Heartbeat + stale detection</td><td>✅ Implemented</td><td>✅ session::mod.rs, session::repository.rs, schema.sql</td><td>postgres_redis_integration tests</td></tr><tr><td>Concurrent Collision</td><td>LOW</td><td>Single port, unique (IP, port)</td><td>✅ By design</td><td>✅ network::udp_server.rs</td><td>Multi-region ⏳</td></tr></tbody></table><hr><h2 id="assumptions-limitations" tabindex="-1">Assumptions &amp; Limitations <a class="header-anchor" href="#assumptions-limitations" aria-label="Permalink to &quot;Assumptions &amp; Limitations&quot;">​</a></h2><ol><li><strong>Trusted LAN:</strong> System assumes attackers are NOT on the network. For public internet, add encryption (QUIC/TLS).</li><li><strong>Deterministic Simulation:</strong> Assumes all logic is stateless and deterministic (no RNG in core game loop).</li><li><strong>No Secrets in Packets:</strong> Plaintext UDP means no confidentiality. IPs, player IDs, state checksums are visible.</li><li><strong>Single-Threaded UDP:</strong> Server processes handshakes sequentially; no built-in rate limiting yet (⏳).</li></ol><hr><h2 id="recommendations-for-production" tabindex="-1">Recommendations for Production <a class="header-anchor" href="#recommendations-for-production" aria-label="Permalink to &quot;Recommendations for Production&quot;">​</a></h2><ol><li><strong>Add QUIC/TLS encryption</strong> (Phase 2).</li><li><strong>Implement rate limiting</strong> per IP / per session (Phase 2).</li><li><strong>Add DDoS monitoring</strong> and alerting (Phase 3).</li><li><strong>Enable AI cheat detection</strong> for large-scale deployments (Phase 2).</li><li><strong>Deploy in trusted VPC</strong> or behind firewall.</li><li><strong>Monitor orphan session cleanup</strong> logs for anomalies.</li></ol><hr><h2 id="review-sign-off" tabindex="-1">Review &amp; Sign-Off <a class="header-anchor" href="#review-sign-off" aria-label="Permalink to &quot;Review &amp; Sign-Off&quot;">​</a></h2><ul><li><strong>Author:</strong> Rollback Netcode Team</li><li><strong>Reviewed:</strong> 2026-10-10</li><li><strong>Approved:</strong> Pending security audit</li></ul><hr><p><strong>Next:</strong> Security audit by external firm (⏳ Phase 3)</p>',95)])])}const h=t(n,[["render",i]]);export{u as __pageData,h as default};
